/**
 * Standalone reimplementations of small tnaj helpers that DO NOT import
 * from `tnaj` — keeps tnaj-light's bundle free of the markov.ts module
 * (and therefore free of the pure-TS markovOrderTest / passageTime /
 * markovStability that share that file).
 *
 * Why these specifically:
 *   - `kgramCounts` is used by the carm-tnaW2 notebook's simplicial-pathway
 *     viz cell.
 *   - `extractTrajectories` is the canonical SequenceData → trajectories
 *     converter; the notebook calls it to prepare data for kgramCounts.
 *
 * Both implementations are byte-equivalent to tnaj's. The `HON_SEP`
 * separator and the lex-sort node order match tnaj for downstream
 * compatibility.
 */
import type { TNA, SequenceData } from '../core/index.js';

const HON_SEP = '\x01';

export interface KgramCounts {
  nodes: string[];
  nodeCounts: Map<string, number>;
  edges: { from: string; to: string; weight: number }[];
}

/**
 * Mirrors tnaj's `extractTrajectories`. Accepts either a TNA model (with
 * .data attached) or a raw SequenceData / string[][]. Strips trailing
 * nulls per row and drops rows shorter than 2.
 */
export function extractTrajectories(
  data: TNA | SequenceData | string[][],
): string[][] {
  if (
    data !== null &&
    typeof data === 'object' &&
    !Array.isArray(data) &&
    'weights' in (data as object)
  ) {
    const model = data as TNA;
    if (!model.data) {
      throw new Error(
        'extractTrajectories: TNA model does not contain data. Rebuild with buildTna().',
      );
    }
    return sequenceDataToTrajectories(model.data);
  }
  if (!Array.isArray(data)) {
    throw new Error('extractTrajectories: data must be an array of trajectories');
  }
  return sequenceDataToTrajectories(data as SequenceData);
}

function sequenceDataToTrajectories(data: SequenceData | string[][]): string[][] {
  const out: string[][] = [];
  for (const rawSeq of data) {
    if (!Array.isArray(rawSeq)) continue;
    let lastNonNull = -1;
    for (let i = 0; i < rawSeq.length; i++) {
      const v = rawSeq[i];
      if (v !== null && v !== undefined && (typeof v !== 'number' || !Number.isNaN(v))) {
        lastNonNull = i;
      }
    }
    if (lastNonNull < 0) continue;
    const traj: string[] = [];
    for (let i = 0; i <= lastNonNull; i++) {
      const v = rawSeq[i];
      if (v === null || v === undefined) continue;
      traj.push(String(v));
    }
    if (traj.length >= 2) out.push(traj);
  }
  return out;
}

/**
 * Mirrors tnaj's `kgramCounts`. Counts k-grams across all trajectories
 * and the edges between consecutive k-grams within each trajectory.
 * Nodes are returned lex-sorted, matching tnaj's R-parity contract.
 */
export function kgramCounts(trajectories: string[][], k: number): KgramCounts {
  if (k < 1) throw new Error('kgramCounts: k must be >= 1');
  const nodeCounts = new Map<string, number>();
  const edgeCounts = new Map<string, number>();
  const EDGE_SEP = '\x02';

  for (const traj of trajectories) {
    const n = traj.length;
    if (n < k) continue;
    const kgrams: string[] = [];
    for (let i = 0; i + k <= n; i++) {
      const kg = traj.slice(i, i + k).join(HON_SEP);
      kgrams.push(kg);
      nodeCounts.set(kg, (nodeCounts.get(kg) ?? 0) + 1);
    }
    for (let i = 0; i + 1 < kgrams.length; i++) {
      const key = `${kgrams[i]}${EDGE_SEP}${kgrams[i + 1]}`;
      edgeCounts.set(key, (edgeCounts.get(key) ?? 0) + 1);
    }
  }
  const nodes = Array.from(nodeCounts.keys()).sort();
  const edges: { from: string; to: string; weight: number }[] = [];
  for (const [key, weight] of edgeCounts) {
    const sepIdx = key.indexOf(EDGE_SEP);
    edges.push({
      from: key.slice(0, sepIdx),
      to: key.slice(sepIdx + 1),
      weight,
    });
  }
  return { nodes, nodeCounts, edges };
}
